uint16_t opeu_cargo_drop_due(uint8_t ds[65536], HostEvent event) {
  CARGO_P p;
  p = SIDE_CARGO;
  if (WORD(p, planes, 8) != 0) {
    SUB_BYTE(FIELD(p, hours, 11), 1);
    if (SUB_BYTE(FIELD(p, delay, 10), 1) == 0) {
      switch (REPORT(TEXT_7BB4, BYTE(p, hours, 11))) {
        case 0: return 1;
        case 1: BYTE(p, delay, 10) = 1; break;
        case 2: SET_WORD(p, planes, 8, 0); break;
      }
    }
  }
  return 0;
}

void opeu_cargo_distribute(uint8_t ds[65536], uint16_t cargo, uint16_t amount) {
  uint16_t v[3], w;
  uint8_t  i;
  v[0] = WORD(cargo, ammo, 2);
  v[1] = WORD(cargo, fuel, 4);
  v[2] = WORD(cargo, food, 6);
  while (amount != 0) {
    if ((v[2] | v[1] | v[0]) == 0)
      break;
    for (i = 0; i < 3; i++) {
      w = opeu_min16(RANDOM(amount + 1), v[i]);
      opeu_sub_word(w, &v[i]);
      amount -= w;
    }
  }
  SET_WORD(cargo, ammo, 2, v[0]);
  SET_WORD(cargo, fuel, 4, v[1]);
  SET_WORD(cargo, food, 6, v[2]);
}

void opeu_cargo_drop_present(uint8_t ds[65536], HostEvent event) {
  if (STATUS(SIDE) == 1)
    MESSAGE(TEXT_7BBF, PERSON(RECORD_MASK(SIDE_RECORD_OF(SIDE, 1)), 6));
  else
    MESSAGE(TEXT_7BD2, SIDE_RECORD_OF(OPPOSITE(SIDE), 3));
  CUE();
}

/* Local names are chosen for C 6.0a's frame layout (slots follow the sum of
 * a name's characters mod 16): px8/sy9 plane pixel position, mx/my target
 * cell, o0/o19/o28 a unit's or objective's ammunition/fuel/food before the
 * drop, a5/b4/f its capacities, m9 the saved map mode, w surviving planes. */
void opeu_cargo_drop_event(uint8_t ds[65536], HostEvent event, uint16_t bp) {
  uint8_t m9;
  FRAME_WORD(a5, 0x16);
  FRAME_WORD(b4, 0x14);
  FRAME_WORD(f, 0x12);
  SIDE_P      s3;
  uint8_t     my, mx;
  OBJECTIVE_P o6;
  CARGO_P     drop;
  FRAME_WORD(sy9, 6);
  UNIT_P u;
  FRAME_WORD(px8, 2);
  uint16_t w, o19, o28;
  BUFFER(text4, 100, 0x8c);
  BUFFER(name8, 12, 0x28);
  uint16_t i, o0;
  s3   = SIDE_RECORD;
  drop = CARGO_OF(s3);
  mx   = BYTE(drop, x, 0);
  my   = BYTE(drop, y, 1);
  w    = WORD(drop, planes, 8);
  SUB_WORD(w, FIELD(s3, planes, 0xe));
  SUB_WORD(WORD(drop, ammo, 2), FIELD(s3, ammo, 0));
  SUB_WORD(WORD(drop, fuel, 4), FIELD(s3, fuel, 2));
  SUB_WORD(WORD(drop, food, 6), FIELD(s3, food, 4));
  opeu_sub_word(DAMAGE(mx, my, opeu_min16(w, 0x1d) / 10), &w);
  DISTRIBUTE(drop, (WORD(drop, planes, 8) - w) * 3000);
  m9       = MAP_MODE;
  MAP_MODE = 1;
  CENTER(mx, my, FOR_STATUS(SIDE));
  SET_LW(px8, mx);
  SET_LW(sy9, my);
  VIEW_PIXEL(REF(px8), REF(sy9));
  for (i = 0x15c; i >= 0x54; i--) {
    if (i <= 0x114 && w == 0) {
      DESTROYED(TEXT_7BEC);
      break;
    }
    DRAW(LW(px8), i, SIDE);
    if (LW(sy9) == i)
      SHOW();
    if ((uint16_t)(LW(sy9) - i) == 0x20) {
      MUSIC7();
      if ((u = UNIT_AT(mx, my)) != 0) {
        CAPACITIES(u, REF(a5), REF(b4), REF(f));
        o0  = WORD(u, ammo, 6);
        o19 = WORD(u, fuel, 8);
        o28 = WORD(u, food, 10);
        ADD_TO(drop, ammo, 2,
               o0 - ADD_WORD(WORD(drop, ammo, 2), FIELD(u, ammo, 6), LW(a5)));
        ADD_TO(drop, fuel, 4,
               o19 - ADD_WORD(WORD(drop, fuel, 4), FIELD(u, fuel, 8), LW(b4)));
        ADD_TO(drop, food, 6,
               o28 - ADD_WORD(WORD(drop, food, 6), FIELD(u, food, 10), LW(f)));
        if (UNIT_SIDE(u) == SIDE) {
          FORMAT_UNIT(text4, u, name8, o0, o19, o28);
          MESSAGE(text4, SIDE_RECORD_OF(SIDE, 3));
        }
      }
      if ((o6 = OBJECTIVE_AT(mx, my)) != 0) {
        o0  = WORD(o6, ammo, 0x17);
        o19 = WORD(o6, fuel, 0x19);
        o28 = WORD(o6, food, 0x1b);
        ADD_TO(
            drop, ammo, 2,
            o0 - ADD_WORD(WORD(drop, ammo, 2), FIELD(o6, ammo, 0x17), 60000u));
        ADD_TO(
            drop, fuel, 4,
            o19 - ADD_WORD(WORD(drop, fuel, 4), FIELD(o6, fuel, 0x19), 60000u));
        ADD_TO(
            drop, food, 6,
            o28 - ADD_WORD(WORD(drop, food, 6), FIELD(o6, food, 0x1b), 60000u));
        if (OBJECTIVE_SIDE(o6) == SIDE) {
          FORMAT_OBJECTIVE(text4, o6, o0, o19, o28);
          MESSAGE(text4, SIDE_RECORD_OF(SIDE, 3));
        }
      }
    }
    DELAY(1);
    RESTORE(LW(px8), i);
  }
  MAP_MODE = m9;
  ADD_WORD(WORD(drop, ammo, 2), FIELD(s3, ammo, 0), 60000u);
  ADD_WORD(WORD(drop, fuel, 4), FIELD(s3, fuel, 2), 60000u);
  ADD_WORD(WORD(drop, food, 6), FIELD(s3, food, 4), 60000u);
  if (w != 0) {
    RETURN_PLANES(SIDE, 3);
    ADD_TO(s3, returning, 0x12, w);
  }
  SET_WORD(drop, planes, 8, 0);
}

void opeu_air_operations(uint8_t ds[65536], HostEvent event, uint16_t sp) {
  for (SIDE = 0; SIDE < 2; SIDE++) {
    if (STRIKE_DUE())
      STRIKE_EVENT();
    if (PARA_DUE()) {
      PARA_EVENT();
      FLAGS(SIDE) &= ~0x10;
    }
    if (CARGO_DUE()) {
      CARGO_EVENT();
      FLAGS(SIDE) &= ~8;
    }
  }
}

